.wsmshirt__media,.wsmshirt__polna{box-shadow:0 14px 34px rgba(140,107,79,.22);border:1px solid rgba(140,107,79,.25)}
.wsmshirt__k{border:1px solid rgba(140,107,79,.35);border-radius:16px;box-shadow:0 6px 18px rgba(0,0,0,.05);transition:transform .2s,box-shadow .2s}.wsmshirt__k:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(140,107,79,.22)}
.wsmshirt__pog>div{border:1px solid rgba(140,107,79,.35);border-radius:16px;padding:28px 18px;transition:transform .2s,box-shadow .2s}.wsmshirt__pog>div:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(140,107,79,.22)}
span.wsmshirt__pi{opacity:1;width:58px;height:58px;border-radius:50%;background:#dcd3ca;border:1px solid #8c6b4f;color:#8c6b4f;display:flex;align-items:center;justify-content:center;margin:0 auto 14px}.wsmshirt__pi svg{width:28px;height:28px}
.wsmshirt__red4:not(.wsmshirt__pog)>div{background:#fff;border:1px solid rgba(140,107,79,.35);border-radius:16px;padding:24px 16px;box-shadow:0 6px 18px rgba(0,0,0,.05)}.wsmshirt__red3 span.wsmshirt__pi{width:44px;height:44px;margin-bottom:8px}.wsmshirt__red3 .wsmshirt__pi svg{width:22px;height:22px}.wsmshirt__red3>div{border-color:rgba(140,107,79,.35)}
.wsmshirt__pog strong{color:#1c1c1c}.wsmshirt__st,.wsmshirt__kv li::before{background:#8c6b4f}.wsmshirt__tab th{background:#8c6b4f!important}
.wsmshirt__ti{background:linear-gradient(135deg,#8c6b4f,#a58c76);box-shadow:0 6px 14px rgba(140,107,79,.30)}.wsmshirt__tk{border-color:rgba(140,107,79,.30)}
.wsmshirt__ime{display:flex;align-items:center;gap:10px}.wsmshirt__av{flex:0 0 34px;width:34px;height:34px;border-radius:50%;background:#dcd3ca;border:1px solid #8c6b4f;color:#8c6b4f;font-style:normal;font-weight:800;font-size:14px;display:inline-flex;align-items:center;justify-content:center}
div.wsmshirt__pog{text-align:center;border:1px solid rgba(140,107,79,.35);border-radius:16px;transition:transform .2s,box-shadow .2s}div.wsmshirt__pog:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(140,107,79,.22)}div.wsmshirt__pog>strong,div.wsmshirt__pog>span:not(.wsmshirt__pi){display:block}
.wsmshirt__k--ik .wsmshirt__kt{text-align:center;padding:28px 20px}
.wsmshirt__pus{color:#8c6b4f}.wsmshirt__plavo{background:#8c6b4f;margin-top:-72px}.wsmshirt__k--temna{background:#8c6b4f}
@media (max-width:860px){.wsmshirt__s{padding:46px 0}.wsmshirt__s.wsmshirt__traka{padding:30px 0}.wsmshirt__plavo{margin-top:-46px}.wsmshirt__pog>div{padding:22px 12px}}
@media (max-width:767px){.wsmshirt__v{padding:0 16px}}
